// Signature/stamp drawn on downloaded invoice PDFs (see lib/pdf.ts).
// Paste the base64 of the PNG between the quotes, with or without the
// "data:image/png;base64," prefix. Leave empty to omit the stamp.
const STAMP_BASE64: string = ''

export const STAMP_SRC: string | null = STAMP_BASE64
  ? STAMP_BASE64.startsWith('data:')
    ? STAMP_BASE64
    : `data:image/png;base64,${STAMP_BASE64}`
  : null
